import{_ as a}from"./chunks/infuse-custom-catalog-items.CH7-HJyD.js";import{_ as o,o as t,c as i,a2 as r}from"./chunks/framework.lxr64Vqo.js";const h=JSON.parse('{"title":"🤖 AI & Custom Catalogs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai-catalogs.md","filePath":"guide/ai-catalogs.md","lastUpdated":1795112636000}'),s={name:"guide/ai-catalogs.md"};function l(n,e,d,c,u,m){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="🤖-ai-custom-catalogs" tabindex="-1">🤖 AI &amp; Custom Catalogs <a class="header-anchor" href="#🤖-ai-custom-catalogs" aria-label="Permalink to &quot;🤖 AI &amp; Custom Catalogs&quot;">​</a></h1><p>One of NoxMedia&#39;s most powerful capabilities is <strong>Dynamic Custom Shelves</strong>. Instead of rigid generic genres, you can create tailored, intelligent collections curated by AI or fine-tuned rules that reflect your exact viewing tastes.</p><hr><h2 id="✨-what-are-custom-catalogs" tabindex="-1">✨ What are Custom Catalogs? <a class="header-anchor" href="#✨-what-are-custom-catalogs" aria-label="Permalink to &quot;✨ What are Custom Catalogs?&quot;">​</a></h2><p>Custom catalogs are dynamic playlists that index and filter your Telegram library on the fly.</p><p>Examples of popular shelves:</p><ul><li>🕵️‍♂️ <em>Murder Mystery &amp; Dark Whodunit</em></li><li>🌌 <em>Sci-Fi Space Operas &amp; Cyberpunk</em></li><li>🏆 <em>A24 &amp; Indie Cinema Classics</em></li><li>⚔️ <em>Shonen Anime with Peak Animation</em></li><li>🍿 <em>4K Dolby Vision Popcorn Blockbusters</em></li></ul><hr><h2 id="🧠-ai-powered-curation-gemini-openrouter" tabindex="-1">🧠 AI-Powered Curation (Gemini &amp; OpenRouter) <a class="header-anchor" href="#🧠-ai-powered-curation-gemini-openrouter" aria-label="Permalink to &quot;🧠 AI-Powered Curation (Gemini &amp; OpenRouter)&quot;">​</a></h2><p>NoxMedia integrates directly with large language models to curate playlists from your indexed media:</p><ol><li>In NoxMedia Settings, add your free <strong>Google Gemini API Key</strong> or <strong>OpenRouter API Key</strong>.</li><li>Go to <strong>Catalogs</strong> → <strong>Create New Shelf</strong> → <strong>AI Assistant</strong>.</li><li>Enter your prompt in plain English: <blockquote><p><em>&quot;Find all psychological thrillers, neo-noir, and investigative murder mysteries with dark atmospheres and high suspense.&quot;</em></p></blockquote></li><li>NoxMedia&#39;s AI analyzes your indexed database, cross-references movie themes, plots, and tags, and builds your shelf automatically.</li></ol><hr><h2 id="🛠️-manual-rule-based-filters" tabindex="-1">🛠️ Manual Rule-Based Filters <a class="header-anchor" href="#🛠️-manual-rule-based-filters" aria-label="Permalink to &quot;🛠️ Manual Rule-Based Filters&quot;">​</a></h2><p>If you prefer exact granular control, you can create shelves based on rules:</p><ul><li><strong>Genre Matching</strong>: Include or exclude genres (e.g., <code>Sci-Fi</code> + <code>Thriller</code>, exclude <code>Horror</code>).</li><li><strong>Resolution &amp; Quality</strong>: Only include <code>4K UHD</code> or <code>HDR10 / Dolby Vision</code> files.</li><li><strong>Year &amp; Decades</strong>: Create retro shelves (e.g. <em>80s Action</em>, <em>90s Nostalgia</em>).</li><li><strong>Ratings</strong>: Minimum TMDB score (e.g., <code>Score ≥ 7.5</code>).</li><li><strong>Keywords &amp; Directors</strong>: Filter by tags like <code>Christopher Nolan</code>, <code>Studio Ghibli</code>, <code>Time Travel</code>.</li></ul><hr><h2 id="📱-cross-client-compatibility" tabindex="-1">📱 Cross-Client Compatibility <a class="header-anchor" href="#📱-cross-client-compatibility" aria-label="Permalink to &quot;📱 Cross-Client Compatibility&quot;">​</a></h2><p>Once a shelf is created in NoxMedia, it is instantly broadcast to all your connected players:</p><ul><li><strong>Infuse</strong>: Appears as a dedicated folder in <strong>Files → NoxMedia</strong>. Star it to display it directly on your Apple TV / iPad Home Screen.</li><li><strong>Stremio</strong>: Appears on the <strong>Discover</strong> board and Home tab alongside standard catalogs.</li><li><strong>Nuvio</strong>: Seamlessly integrates into your custom provider feeds.</li></ul><div class="screenshot-frame"><img src="'+a+'" alt="Murder Mystery Dark Custom Shelf in Infuse"><div class="screenshot-caption">The &quot;Murder Mystery Dark&quot; AI shelf streamed directly inside Infuse on iPad.</div></div>',20)])])}const y=o(s,[["render",l]]);export{h as __pageData,y as default};
